CREATE INDEX provisioning_runtime_claim_identity ON provisioning_runtime_claims ( adapter, runtime_session, terminal_id );
-- index quarantined_provisioning_runtime_identity on quarantined_provisioning_runtime_bindings
CREATE INDEX quarantined_provisioning_runtime_identity ON quarantined_provisioning_runtime_bindings ( adapter, runtime_session, terminal_id );
-- index retired_runtime_provider_sessions on retired_runtime_bindings
CREATE INDEX retired_runtime_provider_sessions ON retired_runtime_bindings ( adapter, runtime_session, provider_session_source, provider_session_provider, provider_session_kind, provider_session_value );
-- index summary_workers_by_parent on summary_worker_commands
CREATE INDEX summary_workers_by_parent ON summary_worker_commands(project_id, parent_worker_id, created_at_unix_ms);
-- index yard_orchestrator_routes_by_created on yard_orchestrator_route_commands
CREATE INDEX yard_orchestrator_routes_by_created ON yard_orchestrator_route_commands(target_project_id, command_id);
-- table agent_profile_files on agent_profile_files
CREATE TABLE agent_profile_files ( profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), path TEXT NOT NULL, media_type TEXT NOT NULL, content TEXT NOT NULL, sha256 TEXT NOT NULL CHECK (length(sha256) = 64), PRIMARY KEY (profile_id, profile_version, path), FOREIGN KEY (profile_id, profile_version) REFERENCES agent_profile_revisions(profile_id, profile_version) ON DELETE RESTRICT ) STRICT;
-- table agent_profile_revisions on agent_profile_revisions
CREATE TABLE agent_profile_revisions ( profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), format_api_version TEXT NOT NULL, canonical_manifest_json TEXT NOT NULL CHECK (json_valid(canonical_manifest_json)), original_manifest_json TEXT NOT NULL CHECK (json_valid(original_manifest_json)), validation_report_json TEXT NOT NULL CHECK (json_valid(validation_report_json)), source TEXT NOT NULL CHECK (source IN ('worker_profile_migration', 'worker_profile_api', 'agent_profile_api')), created_at_unix_ms INTEGER NOT NULL, PRIMARY KEY (profile_id, profile_version), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table archived_projects on archived_projects
CREATE TABLE archived_projects ( project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, command_id TEXT NOT NULL UNIQUE REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), expected_orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_orchestrator_worker_version INTEGER NOT NULL CHECK (expected_orchestrator_worker_version > 0), expected_orchestrator_runtime_version INTEGER CHECK ( expected_orchestrator_runtime_version IS NULL OR expected_orchestrator_runtime_version > 0 ), result_project_version INTEGER NOT NULL CHECK (result_project_version > 0), result_orchestrator_worker_version INTEGER NOT NULL CHECK (result_orchestrator_worker_version > 0), runtime_adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, archived_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table artifacts on artifacts
CREATE TABLE artifacts ( id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, assignment_id TEXT NOT NULL, attempt_id TEXT NOT NULL, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('markdown', 'html')), media_type TEXT NOT NULL CHECK (media_type IN ('text/markdown', 'text/html')), display_name TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK (byte_size > 0 AND byte_size <= 1048576), sha256 TEXT NOT NULL CHECK (length(sha256) = 64), source TEXT NOT NULL CHECK (source IN ('upload')), created_by TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, UNIQUE (id, assignment_id, attempt_id), FOREIGN KEY (assignment_id, project_id) REFERENCES assignments(id, project_id) ON DELETE RESTRICT, FOREIGN KEY (attempt_id, assignment_id) REFERENCES assignment_attempts(id, assignment_id) ON DELETE RESTRICT ) STRICT;
-- table assignment_attempts on assignment_attempts
CREATE TABLE "assignment_attempts" ( id TEXT PRIMARY KEY NOT NULL, assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE RESTRICT, ordinal INTEGER NOT NULL CHECK (ordinal > 0), lifecycle TEXT NOT NULL CHECK ( lifecycle IN ( 'starting', 'active', 'handing_off', 'handed_off', 'completed', 'failed' ) ), error_message TEXT, version INTEGER NOT NULL CHECK (version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, UNIQUE (id, assignment_id), UNIQUE (assignment_id, ordinal), CHECK ( (lifecycle = 'failed' AND error_message IS NOT NULL) OR (lifecycle <> 'failed' AND error_message IS NULL) ) ) STRICT;
-- table assignment_prompt_commands on assignment_prompt_commands
CREATE TABLE assignment_prompt_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL, assignment_id TEXT NOT NULL, attempt_id TEXT NOT NULL, expected_assignment_version INTEGER NOT NULL CHECK (expected_assignment_version > 0), expected_attempt_version INTEGER NOT NULL CHECK (expected_attempt_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, FOREIGN KEY (assignment_id, project_id) REFERENCES assignments(id, project_id) ON DELETE RESTRICT, FOREIGN KEY (attempt_id, assignment_id) REFERENCES assignment_attempts(id, assignment_id) ON DELETE RESTRICT, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table assignments on assignments
CREATE TABLE "assignments" ( id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, allocation_id TEXT NOT NULL UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, objective TEXT NOT NULL, role TEXT NOT NULL, isolation_policy TEXT NOT NULL CHECK (isolation_policy IN ('project_workspace')), lifecycle TEXT NOT NULL CHECK ( lifecycle IN ( 'allocating', 'active', 'handing_off', 'handed_off', 'completed', 'failed' ) ), version INTEGER NOT NULL CHECK (version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, UNIQUE (id, project_id), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table automatic_summary_request_watermarks on automatic_summary_request_watermarks
CREATE TABLE automatic_summary_request_watermarks ( request_kind TEXT NOT NULL CHECK (request_kind IN ('superintendent_project', 'project_worker')), target_id TEXT NOT NULL CHECK (length(target_id) BETWEEN 1 AND 120), claimed_at_unix_ms INTEGER NOT NULL, PRIMARY KEY (request_kind, target_id) ) STRICT;
-- table automation_create_command_projects on automation_create_command_projects
CREATE TABLE automation_create_command_projects ( command_id TEXT NOT NULL REFERENCES automation_create_commands(command_id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, PRIMARY KEY (command_id, project_id) ) STRICT;
-- table automation_create_commands on automation_create_commands
CREATE TABLE automation_create_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, automation_id TEXT NOT NULL UNIQUE REFERENCES automations(id) ON DELETE RESTRICT, name TEXT NOT NULL, scope_kind TEXT NOT NULL CHECK ( scope_kind IN ( 'yard_orchestrator', 'project_orchestrator', 'workstream_coordination_node' ) ), scope_project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, scope_node_id TEXT REFERENCES coordination_nodes(id) ON DELETE RESTRICT, schedule_hour INTEGER NOT NULL CHECK (schedule_hour BETWEEN 0 AND 23), schedule_minute INTEGER NOT NULL CHECK (schedule_minute BETWEEN 0 AND 59), schedule_timezone TEXT NOT NULL, prompt_template TEXT NOT NULL, next_run_at_unix_ms INTEGER NOT NULL, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, result_version INTEGER NOT NULL CHECK (result_version > 0), CHECK ( ( scope_kind = 'yard_orchestrator' AND scope_project_id IS NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'project_orchestrator' AND scope_project_id IS NOT NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'workstream_coordination_node' AND scope_project_id IS NULL AND scope_node_id IS NOT NULL ) ) ) STRICT;
-- table automation_pause_commands on automation_pause_commands
CREATE TABLE automation_pause_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), paused INTEGER NOT NULL CHECK (paused IN (0, 1)), requested_next_run_at_unix_ms INTEGER, result_version INTEGER NOT NULL CHECK (result_version > 0), CHECK ( (paused = 1 AND requested_next_run_at_unix_ms IS NULL) OR (paused = 0 AND requested_next_run_at_unix_ms IS NOT NULL) ) ) STRICT;
-- table automation_placement_commands on automation_placement_commands
CREATE TABLE automation_placement_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, result_version INTEGER NOT NULL CHECK (result_version > 0) ) STRICT;
-- table automation_placements on automation_placements
CREATE TABLE automation_placements ( automation_id TEXT PRIMARY KEY NOT NULL REFERENCES automations(id) ON DELETE CASCADE, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, version INTEGER NOT NULL CHECK (version > 0), updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table automation_run_now_commands on automation_run_now_commands
CREATE TABLE automation_run_now_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), run_id TEXT NOT NULL UNIQUE REFERENCES automation_runs(id) ON DELETE RESTRICT ) STRICT;
-- table automation_run_projects on automation_run_projects
CREATE TABLE automation_run_projects ( run_id TEXT NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, PRIMARY KEY (run_id, project_id) ) STRICT;
-- table automation_runs on automation_runs
CREATE TABLE automation_runs ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(id) = 36 AND lower(id) = id AND id NOT GLOB '*[^0-9a-f-]*' AND substr(id, 9, 1) = '-' AND substr(id, 14, 1) = '-' AND substr(id, 19, 1) = '-' AND substr(id, 24, 1) = '-' ), automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE RESTRICT, scope_kind TEXT NOT NULL CHECK ( scope_kind IN ( 'yard_orchestrator', 'project_orchestrator', 'workstream_coordination_node' ) ), scope_project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, scope_node_id TEXT REFERENCES coordination_nodes(id) ON DELETE RESTRICT, automation_version INTEGER NOT NULL CHECK (automation_version > 0), version INTEGER NOT NULL CHECK (version > 0), trigger TEXT NOT NULL CHECK (trigger IN ('manual', 'scheduled')), status TEXT NOT NULL CHECK (status IN ('pending', 'submitted', 'failed', 'ambiguous')), prompt_template TEXT NOT NULL, dispatch_command_id TEXT NOT NULL UNIQUE, requested_by TEXT NOT NULL, scheduled_for_unix_ms INTEGER, next_due_after_claim_unix_ms INTEGER, runtime_status TEXT, error_message TEXT, submitted_at_unix_ms INTEGER, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( ( scope_kind = 'yard_orchestrator' AND scope_project_id IS NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'project_orchestrator' AND scope_project_id IS NOT NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'workstream_coordination_node' AND scope_project_id IS NULL AND scope_node_id IS NOT NULL ) ), CHECK ( ( trigger = 'manual' AND scheduled_for_unix_ms IS NULL AND next_due_after_claim_unix_ms IS NULL ) OR ( trigger = 'scheduled' AND scheduled_for_unix_ms IS NOT NULL AND next_due_after_claim_unix_ms IS NOT NULL ) ), CHECK ( ( status = 'pending' AND runtime_status IS NULL AND error_message IS NULL AND submitted_at_unix_ms IS NULL ) OR ( status = 'submitted' AND runtime_status IS NOT NULL AND error_message IS NULL AND submitted_at_unix_ms IS NOT NULL ) OR ( status IN ('failed', 'ambiguous') AND runtime_status IS NULL AND error_message IS NOT NULL AND submitted_at_unix_ms IS NULL ) ) ) STRICT;
-- table automation_selected_projects on automation_selected_projects
CREATE TABLE automation_selected_projects ( automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, PRIMARY KEY (automation_id, project_id) ) STRICT;
-- table automation_update_command_projects on automation_update_command_projects
CREATE TABLE automation_update_command_projects ( command_id TEXT NOT NULL REFERENCES automation_update_commands(command_id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, PRIMARY KEY (command_id, project_id) ) STRICT;
-- table automation_update_commands on automation_update_commands
CREATE TABLE automation_update_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), name TEXT NOT NULL, scope_kind TEXT NOT NULL CHECK ( scope_kind IN ( 'yard_orchestrator', 'project_orchestrator', 'workstream_coordination_node' ) ), scope_project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, scope_node_id TEXT REFERENCES coordination_nodes(id) ON DELETE RESTRICT, schedule_hour INTEGER NOT NULL CHECK (schedule_hour BETWEEN 0 AND 23), schedule_minute INTEGER NOT NULL CHECK (schedule_minute BETWEEN 0 AND 59), schedule_timezone TEXT NOT NULL, prompt_template TEXT NOT NULL, requested_next_run_at_unix_ms INTEGER, result_version INTEGER NOT NULL CHECK (result_version > 0), CHECK ( ( scope_kind = 'yard_orchestrator' AND scope_project_id IS NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'project_orchestrator' AND scope_project_id IS NOT NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'workstream_coordination_node' AND scope_project_id IS NULL AND scope_node_id IS NOT NULL ) ) ) STRICT;
-- table automations on automations
CREATE TABLE automations ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(id) = 36 AND lower(id) = id AND id NOT GLOB '*[^0-9a-f-]*' AND substr(id, 9, 1) = '-' AND substr(id, 14, 1) = '-' AND substr(id, 19, 1) = '-' AND substr(id, 24, 1) = '-' ), name TEXT NOT NULL CHECK (length(name) > 0), scope_kind TEXT NOT NULL CHECK ( scope_kind IN ( 'yard_orchestrator', 'project_orchestrator', 'workstream_coordination_node' ) ), scope_project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, scope_node_id TEXT REFERENCES coordination_nodes(id) ON DELETE RESTRICT, schedule_hour INTEGER NOT NULL CHECK (schedule_hour BETWEEN 0 AND 23), schedule_minute INTEGER NOT NULL CHECK (schedule_minute BETWEEN 0 AND 59), schedule_timezone TEXT NOT NULL CHECK (length(schedule_timezone) > 0), prompt_template TEXT NOT NULL CHECK (length(prompt_template) > 0), state TEXT NOT NULL CHECK (state IN ('active', 'paused')), next_run_at_unix_ms INTEGER, version INTEGER NOT NULL CHECK (version > 0), created_by TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( ( scope_kind = 'yard_orchestrator' AND scope_project_id IS NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'project_orchestrator' AND scope_project_id IS NOT NULL AND scope_node_id IS NULL ) OR ( scope_kind = 'workstream_coordination_node' AND scope_project_id IS NULL AND scope_node_id IS NOT NULL ) ), CHECK ( (state = 'active' AND next_run_at_unix_ms IS NOT NULL) OR (state = 'paused' AND next_run_at_unix_ms IS NULL) ) ) STRICT;
-- table cleanup_advisor_artifacts on cleanup_advisor_artifacts
CREATE TABLE cleanup_advisor_artifacts ( artifact_id TEXT PRIMARY KEY NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT, run_id TEXT NOT NULL REFERENCES worker_cleanup_runs(id) ON DELETE RESTRICT, target_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, completion_receipt_id TEXT NOT NULL REFERENCES completion_receipts(id) ON DELETE RESTRICT, recommendation TEXT NOT NULL CHECK (recommendation IN ('keep', 'retire', 'review')), evidence_ids_json TEXT NOT NULL CHECK (json_valid(evidence_ids_json)), rationale TEXT NOT NULL, recorded_at_unix_ms INTEGER NOT NULL, UNIQUE (run_id, target_worker_id) ) STRICT;
-- table command_acknowledgements on command_acknowledgements
CREATE TABLE "command_acknowledgements" ( id TEXT PRIMARY KEY NOT NULL, command_type TEXT NOT NULL CHECK ( command_type IN ( 'profile_allocation', 'worker_allocation', 'worker_handoff', 'profile_project_creation', 'completion_receipt', 'assignment_prompt', 'orchestrator_prompt', 'worker_session_end', 'yard_orchestrator_configure', 'yard_orchestrator_prompt', 'project_relationship_create', 'project_relationship_delete', 'yard_orchestrator_route', 'coordination_node_create', 'coordination_node_update', 'coordination_node_placement', 'coordination_node_provision', 'coordination_node_prompt', 'coordination_node_route', 'coordination_snapshot_request', 'automation_create', 'automation_update', 'automation_placement', 'automation_pause', 'automation_run_now', 'project_orchestrator_replacement', 'project_orchestrator_transfer', 'project_archive', 'project_delete', 'worker_delete' ) ), actor TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'succeeded', 'failed', 'ambiguous')), error_message TEXT, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( (status IN ('failed', 'ambiguous') AND error_message IS NOT NULL) OR (status NOT IN ('failed', 'ambiguous') AND error_message IS NULL) ) ) STRICT;
-- table completion_receipt_artifact_links on completion_receipt_artifact_links
CREATE TABLE completion_receipt_artifact_links ( receipt_id TEXT NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), artifact_id TEXT NOT NULL, assignment_id TEXT NOT NULL, attempt_id TEXT NOT NULL, PRIMARY KEY (receipt_id, position), UNIQUE (receipt_id, artifact_id), FOREIGN KEY (receipt_id, assignment_id, attempt_id) REFERENCES completion_receipts(id, assignment_id, attempt_id) ON DELETE RESTRICT, FOREIGN KEY (artifact_id, assignment_id, attempt_id) REFERENCES artifacts(id, assignment_id, attempt_id) ON DELETE RESTRICT ) STRICT;
-- table completion_receipt_artifacts on completion_receipt_artifacts
CREATE TABLE completion_receipt_artifacts ( receipt_id TEXT NOT NULL REFERENCES completion_receipts(id) ON DELETE RESTRICT, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (receipt_id, position) ) STRICT;
-- table completion_receipt_blockers on completion_receipt_blockers
CREATE TABLE completion_receipt_blockers ( receipt_id TEXT NOT NULL REFERENCES completion_receipts(id) ON DELETE RESTRICT, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (receipt_id, position) ) STRICT;
-- table completion_receipt_commands on completion_receipt_commands
CREATE TABLE completion_receipt_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL, assignment_id TEXT NOT NULL, attempt_id TEXT NOT NULL, expected_assignment_version INTEGER NOT NULL CHECK (expected_assignment_version > 0), expected_attempt_version INTEGER NOT NULL CHECK (expected_attempt_version > 0), outcome TEXT NOT NULL CHECK (outcome IN ('completed')), summary TEXT NOT NULL, FOREIGN KEY (assignment_id, project_id) REFERENCES assignments(id, project_id) ON DELETE RESTRICT, FOREIGN KEY (attempt_id, assignment_id) REFERENCES assignment_attempts(id, assignment_id) ON DELETE RESTRICT ) STRICT;
-- table completion_receipt_evidence on completion_receipt_evidence
CREATE TABLE completion_receipt_evidence ( receipt_id TEXT NOT NULL REFERENCES completion_receipts(id) ON DELETE RESTRICT, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (receipt_id, position) ) STRICT;
-- table completion_receipts on completion_receipts
CREATE TABLE completion_receipts ( id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL UNIQUE REFERENCES completion_receipt_commands(command_id) ON DELETE RESTRICT, assignment_id TEXT NOT NULL UNIQUE REFERENCES assignments(id) ON DELETE RESTRICT, attempt_id TEXT NOT NULL UNIQUE REFERENCES assignment_attempts(id) ON DELETE RESTRICT, outcome TEXT NOT NULL CHECK (outcome IN ('completed')), summary TEXT NOT NULL, actor TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (attempt_id, assignment_id) REFERENCES assignment_attempts(id, assignment_id) ON DELETE RESTRICT ) STRICT;
-- table coordination_node_create_commands on coordination_node_create_commands
CREATE TABLE coordination_node_create_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL UNIQUE REFERENCES coordination_nodes(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('workstream', 'knowledge_store')), name TEXT NOT NULL, attached_project_ids TEXT NOT NULL, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL ) STRICT;
-- table coordination_node_placement_commands on coordination_node_placement_commands
CREATE TABLE coordination_node_placement_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, result_version INTEGER NOT NULL CHECK (result_version > 0) ) STRICT;
-- table coordination_node_placements on coordination_node_placements
CREATE TABLE coordination_node_placements ( node_id TEXT PRIMARY KEY NOT NULL REFERENCES coordination_nodes(id) ON DELETE CASCADE, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, version INTEGER NOT NULL CHECK (version > 0), updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table coordination_node_projects on coordination_node_projects
CREATE TABLE coordination_node_projects ( node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, PRIMARY KEY (node_id, project_id) ) STRICT;
-- table coordination_node_prompt_commands on coordination_node_prompt_commands
CREATE TABLE coordination_node_prompt_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_node_version INTEGER NOT NULL CHECK (expected_node_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table coordination_node_provision_commands on coordination_node_provision_commands
CREATE TABLE coordination_node_provision_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), expected_node_version INTEGER NOT NULL CHECK (expected_node_version > 0), worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, result_node_version INTEGER NOT NULL CHECK (result_node_version > 0), finished_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table coordination_node_route_commands on coordination_node_route_commands
CREATE TABLE coordination_node_route_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_node_version INTEGER NOT NULL CHECK (expected_node_version > 0), target_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, target_orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table coordination_node_update_commands on coordination_node_update_commands
CREATE TABLE coordination_node_update_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, expected_version INTEGER NOT NULL CHECK (expected_version > 0), name TEXT NOT NULL, attached_project_ids TEXT NOT NULL, result_version INTEGER NOT NULL CHECK (result_version > 0) ) STRICT;
-- table coordination_nodes on coordination_nodes
CREATE TABLE coordination_nodes ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(id) = 36 AND lower(id) = id AND id NOT GLOB '*[^0-9a-f-]*' AND substr(id, 9, 1) = '-' AND substr(id, 14, 1) = '-' AND substr(id, 19, 1) = '-' AND substr(id, 24, 1) = '-' ), name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('workstream', 'knowledge_store')), worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, workstream_cwd TEXT, knowledge_path TEXT, version INTEGER NOT NULL CHECK (version > 0), created_by TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( ( kind = 'workstream' AND workstream_cwd IS NOT NULL AND knowledge_path IS NULL ) OR ( kind = 'knowledge_store' AND workstream_cwd IS NULL AND knowledge_path IS NOT NULL AND worker_id IS NULL ) ) ) STRICT;
-- table coordination_snapshot_projects on coordination_snapshot_projects
CREATE TABLE coordination_snapshot_projects ( snapshot_id TEXT NOT NULL REFERENCES coordination_snapshots(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, project_version INTEGER NOT NULL CHECK (project_version > 0), orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, folder_path TEXT NOT NULL, collection_status TEXT NOT NULL CHECK (collection_status IN ('pending', 'collected')), delivery_status TEXT NOT NULL CHECK (delivery_status IN ('pending', 'submitted', 'failed', 'ambiguous')), delivery_error TEXT, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, collected_at_unix_ms INTEGER, PRIMARY KEY (snapshot_id, project_id), CHECK ( (collection_status = 'pending' AND collected_at_unix_ms IS NULL) OR (collection_status = 'collected' AND collected_at_unix_ms IS NOT NULL) ), CHECK ( ( delivery_status = 'pending' AND delivery_error IS NULL AND result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL ) OR ( delivery_status = 'submitted' AND delivery_error IS NULL AND result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) OR ( delivery_status IN ('failed', 'ambiguous') AND delivery_error IS NOT NULL AND result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL ) ) ) STRICT;
-- table coordination_snapshots on coordination_snapshots
CREATE TABLE coordination_snapshots ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(id) = 36 AND lower(id) = id AND id NOT GLOB '*[^0-9a-f-]*' AND substr(id, 9, 1) = '-' AND substr(id, 14, 1) = '-' AND substr(id, 19, 1) = '-' AND substr(id, 24, 1) = '-' ), node_id TEXT NOT NULL REFERENCES coordination_nodes(id) ON DELETE RESTRICT, command_id TEXT NOT NULL UNIQUE REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, expected_node_version INTEGER NOT NULL CHECK (expected_node_version > 0), folder_path TEXT NOT NULL, requested_by TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, UNIQUE (node_id, id) ) STRICT;
-- table dedicated_runtime_provision_intents on dedicated_runtime_provision_intents
CREATE TABLE dedicated_runtime_provision_intents ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('yard_orchestrator', 'coordination_node')), target_id TEXT NOT NULL, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), expected_target_version INTEGER NOT NULL CHECK (expected_target_version > 0), runtime_start_confirmed INTEGER NOT NULL DEFAULT 0 CHECK (runtime_start_confirmed IN (0, 1)), result_worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, created_at_unix_ms INTEGER NOT NULL CHECK (created_at_unix_ms >= 0), updated_at_unix_ms INTEGER NOT NULL CHECK (updated_at_unix_ms >= 0) ) STRICT;
-- table deleted_projects on deleted_projects
CREATE TABLE deleted_projects ( project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, command_id TEXT NOT NULL UNIQUE REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, deleted_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table deleted_workers on deleted_workers
CREATE TABLE deleted_workers ( worker_id TEXT PRIMARY KEY NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, command_id TEXT NOT NULL UNIQUE REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), deleted_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table lifecycle_events on lifecycle_events
CREATE TABLE lifecycle_events ( sequence INTEGER PRIMARY KEY AUTOINCREMENT, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL CHECK (aggregate_version > 0), event_type TEXT NOT NULL, source TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table orchestrator_prompt_commands on orchestrator_prompt_commands
CREATE TABLE orchestrator_prompt_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table orchestrator_replacement_runtime_bindings on orchestrator_replacement_runtime_bindings
CREATE TABLE orchestrator_replacement_runtime_bindings ( id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL REFERENCES project_orchestrator_replacement_commands(command_id) ON DELETE RESTRICT, binding_role TEXT NOT NULL CHECK ( binding_role IN ( 'displaced', 'replacement_prepared', 'replacement_started' ) ), worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, allocation_id TEXT REFERENCES worker_allocations(id) ON DELETE RESTRICT, assignment_id TEXT REFERENCES assignments(id) ON DELETE RESTRICT, assignment_version INTEGER CHECK (assignment_version IS NULL OR assignment_version > 0), attempt_id TEXT REFERENCES assignment_attempts(id) ON DELETE RESTRICT, attempt_version INTEGER CHECK (attempt_version IS NULL OR attempt_version > 0), adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), observation_state TEXT NOT NULL CHECK (observation_state IN ('observed', 'missing', 'ambiguous')), process_state TEXT NOT NULL CHECK (process_state IN ('running', 'exited', 'unknown')), observed_status TEXT NOT NULL CHECK (observed_status IN ('idle', 'working', 'blocked', 'done', 'unknown')), state_change_sequence INTEGER NOT NULL CHECK (state_change_sequence >= 0), runtime_revision INTEGER NOT NULL CHECK (runtime_revision >= 0), runtime_version INTEGER NOT NULL CHECK (runtime_version > 0), last_observed_at_unix_ms INTEGER NOT NULL CHECK (last_observed_at_unix_ms >= 0), captured_at_unix_ms INTEGER NOT NULL, objective_delivery_confirmed INTEGER NOT NULL DEFAULT 0 CHECK (objective_delivery_confirmed IN (0, 1)), recovery_outcome TEXT CHECK ( recovery_outcome IS NULL OR recovery_outcome IN ( 'adopted_current', 'absent_converged', 'conflicting_reused', 'present_not_safely_retirable' ) ), recovery_detail TEXT, reconciled_at_unix_ms INTEGER CHECK ( reconciled_at_unix_ms IS NULL OR reconciled_at_unix_ms >= 0 ), recovery_attempts INTEGER NOT NULL DEFAULT 0 CHECK (recovery_attempts >= 0), next_recovery_at_unix_ms INTEGER CHECK ( next_recovery_at_unix_ms IS NULL OR next_recovery_at_unix_ms >= 0 ), UNIQUE (command_id, binding_role), CHECK ( ( binding_role = 'displaced' AND worker_id IS NOT NULL AND allocation_id IS NOT NULL AND ( ( assignment_id IS NULL AND assignment_version IS NULL AND attempt_id IS NULL AND attempt_version IS NULL ) OR ( assignment_id IS NOT NULL AND assignment_version IS NOT NULL AND attempt_id IS NOT NULL AND attempt_version IS NOT NULL ) ) ) OR ( binding_role <> 'displaced' AND worker_id IS NULL AND allocation_id IS NULL AND assignment_id IS NULL AND assignment_version IS NULL AND attempt_id IS NULL AND attempt_version IS NULL ) ), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ), CHECK (owns_tab = 0 OR tab_id IS NOT NULL) ) STRICT;
-- table orchestrator_workflow_profile_current on orchestrator_workflow_profile_current
CREATE TABLE "orchestrator_workflow_profile_current" ( singleton_id INTEGER PRIMARY KEY NOT NULL CHECK (singleton_id = 1), profile_id TEXT NOT NULL DEFAULT 'yard:standard-orchestrator' CHECK (profile_id = 'yard:standard-orchestrator'), current_version INTEGER NOT NULL CHECK (current_version > 0), updated_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (profile_id, current_version) REFERENCES "orchestrator_workflow_profile_revisions"(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table orchestrator_workflow_profile_revisions on orchestrator_workflow_profile_revisions
CREATE TABLE "orchestrator_workflow_profile_revisions" ( profile_id TEXT NOT NULL CHECK (length(profile_id) > 0), version INTEGER NOT NULL CHECK (version > 0), name TEXT NOT NULL CHECK (length(name) > 0), description TEXT NOT NULL CHECK (length(description) > 0), instructions_markdown TEXT NOT NULL CHECK (length(instructions_markdown) > 0), monitor_interval_ms INTEGER NOT NULL CHECK (monitor_interval_ms > 0), commands_json TEXT NOT NULL CHECK (json_valid(commands_json) AND json_type(commands_json) = 'array'), adapter_context_files_json TEXT NOT NULL CHECK ( json_valid(adapter_context_files_json) AND json_type(adapter_context_files_json) = 'array' ), source TEXT NOT NULL CHECK (source IN ('factory', 'user', 'reset')), updated_by TEXT NOT NULL CHECK (length(updated_by) > 0), created_at_unix_ms INTEGER NOT NULL, PRIMARY KEY (profile_id, version) ) STRICT;
-- table orchestrator_workflow_profiles on orchestrator_workflow_profiles
CREATE TABLE "orchestrator_workflow_profiles" ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) > 0), current_version INTEGER NOT NULL CHECK (current_version > 0), updated_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (id, current_version) REFERENCES "orchestrator_workflow_profile_revisions"(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table pane_management_batches on pane_management_batches
CREATE TABLE pane_management_batches ( command_id TEXT PRIMARY KEY NOT NULL, actor TEXT NOT NULL, input_hash TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'succeeded')), result_json TEXT, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( (status = 'pending' AND result_json IS NULL) OR (status = 'succeeded' AND result_json IS NOT NULL) ) ) STRICT;
-- table pane_management_leases on pane_management_leases
CREATE TABLE pane_management_leases ( worker_id TEXT PRIMARY KEY NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, allocation_id TEXT NOT NULL UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, installation_uuid TEXT NOT NULL, herdr_session TEXT NOT NULL, pane_id TEXT NOT NULL, pane_instance_id TEXT NOT NULL, owner_id TEXT NOT NULL, lease_token TEXT NOT NULL, expires_at_unix_ms INTEGER NOT NULL, acquisition_request_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('active', 'recovery_required')), renewal_failures INTEGER NOT NULL DEFAULT 0 CHECK (renewal_failures >= 0), renew_after_unix_ms INTEGER NOT NULL, last_error_code TEXT, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, UNIQUE (herdr_session, pane_id, pane_instance_id), FOREIGN KEY (installation_uuid) REFERENCES yard_installation(installation_uuid) ON DELETE RESTRICT ) STRICT;
-- table profile_allocation_commands on profile_allocation_commands
CREATE TABLE profile_allocation_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), objective TEXT NOT NULL, role TEXT NOT NULL, isolation_policy TEXT NOT NULL CHECK (isolation_policy IN ('project_workspace')), result_worker_id TEXT, result_allocation_id TEXT, result_assignment_id TEXT, FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table profile_launch_audits on profile_launch_audits
CREATE TABLE profile_launch_audits ( command_id TEXT PRIMARY KEY NOT NULL, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), plan_json TEXT NOT NULL CHECK (json_valid(plan_json)), created_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (profile_id, profile_version) REFERENCES agent_profile_revisions(profile_id, profile_version) ON DELETE RESTRICT ) STRICT;
-- table profile_project_creation_commands on profile_project_creation_commands
CREATE TABLE profile_project_creation_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_name TEXT NOT NULL, runtime_adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), orchestrator_objective TEXT NOT NULL, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, result_project_id TEXT UNIQUE REFERENCES projects(id) ON DELETE RESTRICT, result_worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, finished_at_unix_ms INTEGER, workflow_profile_id TEXT NOT NULL DEFAULT 'yard:standard-orchestrator', workflow_profile_version INTEGER NOT NULL DEFAULT 1 CHECK (workflow_profile_version > 0), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT, CHECK ( (result_project_id IS NULL AND result_worker_id IS NULL) OR (result_project_id IS NOT NULL AND result_worker_id IS NOT NULL) ) ) STRICT;
-- table project_orchestrator_replacement_commands on project_orchestrator_replacement_commands
CREATE TABLE project_orchestrator_replacement_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), expected_orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_orchestrator_worker_version INTEGER NOT NULL CHECK (expected_orchestrator_worker_version > 0), expected_orchestrator_runtime_version INTEGER NOT NULL CHECK (expected_orchestrator_runtime_version > 0), profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), objective TEXT NOT NULL, role TEXT NOT NULL, old_session_disposition TEXT NOT NULL CHECK ( old_session_disposition IN ( 'retain_for_inspection', 'retire_after_cutover', 'end_after_cutover' ) ), handoff_artifact_ref TEXT, result_worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, result_allocation_id TEXT UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, result_assignment_id TEXT UNIQUE REFERENCES assignments(id) ON DELETE RESTRICT, finished_at_unix_ms INTEGER, prepare_tab_label TEXT, prepare_intent_at_unix_ms INTEGER CHECK ( prepare_intent_at_unix_ms IS NULL OR prepare_intent_at_unix_ms >= 0 ), prepare_recovery_outcome TEXT CHECK ( prepare_recovery_outcome IS NULL OR prepare_recovery_outcome IN ( 'adopted_current', 'absent_converged', 'conflicting_reused', 'present_not_safely_retirable' ) ), prepare_recovery_detail TEXT, prepare_reconciled_at_unix_ms INTEGER CHECK ( prepare_reconciled_at_unix_ms IS NULL OR prepare_reconciled_at_unix_ms >= 0 ), prepare_recovery_attempts INTEGER NOT NULL DEFAULT 0 CHECK (prepare_recovery_attempts >= 0), prepare_absence_observations INTEGER NOT NULL DEFAULT 0 CHECK (prepare_absence_observations >= 0), prepare_next_recovery_at_unix_ms INTEGER CHECK ( prepare_next_recovery_at_unix_ms IS NULL OR prepare_next_recovery_at_unix_ms >= 0 ), prepare_last_absence_observed_at_unix_ms INTEGER CHECK ( prepare_last_absence_observed_at_unix_ms IS NULL OR prepare_last_absence_observed_at_unix_ms >= 0 ), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT, CHECK ( ( result_worker_id IS NULL AND result_allocation_id IS NULL AND result_assignment_id IS NULL ) OR ( result_worker_id IS NOT NULL AND result_allocation_id IS NOT NULL AND result_assignment_id IS NOT NULL AND finished_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table project_orchestrator_replacement_workflow_pins on project_orchestrator_replacement_workflow_pins
CREATE TABLE project_orchestrator_replacement_workflow_pins ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES project_orchestrator_replacement_commands(command_id) ON DELETE RESTRICT, profile_id TEXT NOT NULL CHECK (length(profile_id) > 0), profile_version INTEGER NOT NULL CHECK (profile_version > 0), FOREIGN KEY (profile_id, profile_version) REFERENCES orchestrator_workflow_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table project_orchestrator_transfer_commands on project_orchestrator_transfer_commands
CREATE TABLE project_orchestrator_transfer_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), expected_orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_orchestrator_worker_version INTEGER NOT NULL CHECK (expected_orchestrator_worker_version > 0), replaced_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, result_project_version INTEGER NOT NULL CHECK (result_project_version > 0), result_worker_version INTEGER NOT NULL CHECK (result_worker_version > 0), result_replaced_worker_version INTEGER NOT NULL CHECK (result_replaced_worker_version > 0), result_allocation_id TEXT NOT NULL UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, result_project_json TEXT NOT NULL, finished_at_unix_ms INTEGER NOT NULL, CHECK (worker_id <> expected_orchestrator_worker_id), CHECK (replaced_worker_id = expected_orchestrator_worker_id) ) STRICT;
-- table project_orchestrator_transfer_runtime_bindings on project_orchestrator_transfer_runtime_bindings
CREATE TABLE project_orchestrator_transfer_runtime_bindings ( command_id TEXT NOT NULL REFERENCES project_orchestrator_transfer_commands(command_id) ON DELETE RESTRICT, binding_role TEXT NOT NULL CHECK (binding_role IN ('candidate', 'displaced')), worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), observation_state TEXT NOT NULL CHECK (observation_state IN ('observed', 'missing', 'ambiguous')), process_state TEXT NOT NULL CHECK (process_state IN ('running', 'exited', 'unknown')), observed_status TEXT NOT NULL CHECK (observed_status IN ('idle', 'working', 'blocked', 'done', 'unknown')), state_change_sequence INTEGER NOT NULL CHECK (state_change_sequence >= 0), runtime_revision INTEGER NOT NULL CHECK (runtime_revision >= 0), runtime_version INTEGER NOT NULL CHECK (runtime_version > 0), last_observed_at_unix_ms INTEGER NOT NULL CHECK (last_observed_at_unix_ms >= 0), PRIMARY KEY (command_id, binding_role), UNIQUE (command_id, worker_id), CHECK (owns_tab = 0 OR tab_id IS NOT NULL), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ) ) STRICT;
-- table project_placements on project_placements
CREATE TABLE "project_placements" ( project_id TEXT PRIMARY KEY NOT NULL REFERENCES "projects"(id) ON DELETE CASCADE, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, version INTEGER NOT NULL CHECK (version > 0), updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table project_relationship_create_commands on project_relationship_create_commands
CREATE TABLE project_relationship_create_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, relationship_id TEXT NOT NULL UNIQUE, source_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, target_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('depends_on')), result_version INTEGER NOT NULL CHECK (result_version > 0), result_created_by TEXT NOT NULL, result_created_at_unix_ms INTEGER NOT NULL, result_updated_at_unix_ms INTEGER NOT NULL, CHECK (source_project_id <> target_project_id) ) STRICT;
-- table project_relationship_delete_commands on project_relationship_delete_commands
CREATE TABLE project_relationship_delete_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, relationship_id TEXT NOT NULL, expected_version INTEGER NOT NULL CHECK (expected_version > 0), deleted_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table project_relationships on project_relationships
CREATE TABLE project_relationships ( id TEXT PRIMARY KEY NOT NULL, source_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, target_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('depends_on')), version INTEGER NOT NULL CHECK (version > 0), created_by TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, UNIQUE (source_project_id, target_project_id, kind), CHECK (source_project_id <> target_project_id) ) STRICT;
-- table project_repositories on project_repositories
CREATE TABLE project_repositories ( id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, root_path TEXT NOT NULL, git_common_dir TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, UNIQUE (project_id, root_path) ) STRICT;
-- table project_workflow_profile_pins on project_workflow_profile_pins
CREATE TABLE "project_workflow_profile_pins" ( project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE, profile_id TEXT NOT NULL CHECK (length(profile_id) > 0), profile_version INTEGER NOT NULL CHECK (profile_version > 0), pinned_by TEXT NOT NULL CHECK (length(pinned_by) > 0), pinned_at_unix_ms INTEGER NOT NULL, FOREIGN KEY (profile_id, profile_version) REFERENCES "orchestrator_workflow_profile_revisions"(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table project_workspace_bindings on project_workspace_bindings
CREATE TABLE "project_workspace_bindings" ( project_id TEXT PRIMARY KEY NOT NULL REFERENCES "projects"(id) ON DELETE CASCADE, adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, UNIQUE (adapter, runtime_session, runtime_workspace_id) ) STRICT;
-- table projects on projects
CREATE TABLE "projects" ( id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, orchestrator_worker_id TEXT NOT NULL UNIQUE REFERENCES "workers"(id) ON DELETE RESTRICT, version INTEGER NOT NULL CHECK (version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table provisioning_runtime_claims on provisioning_runtime_claims
CREATE TABLE provisioning_runtime_claims ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), observation_state TEXT NOT NULL CHECK (observation_state IN ('observed', 'ambiguous')), process_state TEXT NOT NULL CHECK (process_state IN ('running', 'exited', 'unknown')), observed_status TEXT NOT NULL, state_change_sequence INTEGER NOT NULL CHECK (state_change_sequence >= 0), runtime_revision INTEGER NOT NULL CHECK (runtime_revision >= 0), runtime_version INTEGER NOT NULL CHECK (runtime_version > 0), last_observed_at_unix_ms INTEGER NOT NULL CHECK (last_observed_at_unix_ms >= 0), captured_at_unix_ms INTEGER NOT NULL CHECK (captured_at_unix_ms >= 0), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ) ) STRICT;
-- table quarantined_provisioning_runtime_bindings on quarantined_provisioning_runtime_bindings
CREATE TABLE quarantined_provisioning_runtime_bindings ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), observation_state TEXT NOT NULL CHECK (observation_state IN ('observed', 'ambiguous')), process_state TEXT NOT NULL CHECK (process_state IN ('running', 'exited', 'unknown')), observed_status TEXT NOT NULL, state_change_sequence INTEGER NOT NULL CHECK (state_change_sequence >= 0), runtime_revision INTEGER NOT NULL CHECK (runtime_revision >= 0), runtime_version INTEGER NOT NULL CHECK (runtime_version > 0), last_observed_at_unix_ms INTEGER NOT NULL CHECK (last_observed_at_unix_ms >= 0), captured_at_unix_ms INTEGER NOT NULL CHECK (captured_at_unix_ms >= 0), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ) ) STRICT;
-- table retired_runtime_bindings on retired_runtime_bindings
CREATE TABLE "retired_runtime_bindings" ( id TEXT PRIMARY KEY NOT NULL, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, command_id TEXT NOT NULL UNIQUE REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, reason TEXT NOT NULL CHECK ( reason IN ( 'handoff_source', 'worker_session_end', 'project_archive' ) ), adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, retired_at_unix_ms INTEGER NOT NULL, UNIQUE (adapter, runtime_session, terminal_id), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ) ) STRICT;
-- table runtime_cleanup_jobs on runtime_cleanup_jobs
CREATE TABLE "runtime_cleanup_jobs" ( id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, reason TEXT NOT NULL CHECK ( reason IN ( 'handoff_source', 'replaced_orchestrator', 'worker_session_end', 'project_archive' ) ), adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), status TEXT NOT NULL CHECK (status IN ('pending', 'succeeded')), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), last_error TEXT, next_attempt_at_unix_ms INTEGER NOT NULL, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, completed_at_unix_ms INTEGER, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, expected_worker_version INTEGER CHECK (expected_worker_version IS NULL OR expected_worker_version > 0), expected_binding_state TEXT CHECK ( expected_binding_state IS NULL OR expected_binding_state IN ('detached', 'replaced') ), claim_token TEXT, claim_expires_at_unix_ms INTEGER, CHECK ( (status = 'pending' AND completed_at_unix_ms IS NULL) OR (status = 'succeeded' AND completed_at_unix_ms IS NOT NULL) ), CHECK (owns_tab = 0 OR tab_id IS NOT NULL), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ), CHECK ( ( claim_token IS NULL AND claim_expires_at_unix_ms IS NULL ) OR ( status = 'pending' AND claim_token IS NOT NULL AND claim_expires_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table runtime_reconciliation_watermarks on runtime_reconciliation_watermarks
CREATE TABLE runtime_reconciliation_watermarks ( adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, observed_at_unix_ms INTEGER NOT NULL CHECK (observed_at_unix_ms >= 0), PRIMARY KEY (adapter, runtime_session) ) STRICT;
-- table summary_worker_commands on summary_worker_commands
CREATE TABLE summary_worker_commands ( command_id TEXT PRIMARY KEY NOT NULL, actor TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, parent_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_parent_worker_version INTEGER NOT NULL CHECK (expected_parent_worker_version > 0), expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), expected_artifact_id TEXT NOT NULL UNIQUE, objective TEXT NOT NULL, captured_adapter TEXT NOT NULL, captured_runtime_session TEXT NOT NULL, captured_workspace_id TEXT NOT NULL, captured_terminal_id TEXT NOT NULL, captured_tab_id TEXT NOT NULL, captured_pane_id TEXT NOT NULL, captured_pane_instance_id TEXT, captured_provider_session_json TEXT CHECK ( captured_provider_session_json IS NULL OR json_valid(captured_provider_session_json) ), status TEXT NOT NULL CHECK (status IN ('allocating', 'active', 'failed')), result_worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, result_assignment_id TEXT UNIQUE REFERENCES assignments(id) ON DELETE RESTRICT, handoff_command_id TEXT UNIQUE, cleanup_run_id TEXT UNIQUE REFERENCES worker_cleanup_runs(id) ON DELETE RESTRICT, error_message TEXT, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, CHECK ( (status = 'allocating' AND result_worker_id IS NULL AND result_assignment_id IS NULL) OR (status = 'active' AND result_worker_id IS NOT NULL AND result_assignment_id IS NOT NULL) OR (status = 'failed' AND error_message IS NOT NULL) ), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table token_spend_settings on token_spend_settings
CREATE TABLE token_spend_settings ( id INTEGER PRIMARY KEY NOT NULL CHECK (id = 1), superintendent_auto_requests_project_summaries INTEGER NOT NULL CHECK (superintendent_auto_requests_project_summaries IN (0, 1)), project_orchestrators_auto_request_worker_summaries INTEGER NOT NULL CHECK (project_orchestrators_auto_request_worker_summaries IN (0, 1)), scheduled_automatic_summaries INTEGER NOT NULL CHECK (scheduled_automatic_summaries IN (0, 1)), version INTEGER NOT NULL CHECK (version > 0), updated_by TEXT NOT NULL CHECK (length(updated_by) > 0), updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table worker_allocation_commands on worker_allocation_commands
CREATE TABLE worker_allocation_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), requested_profile_id TEXT, requested_profile_version INTEGER, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), objective TEXT NOT NULL, role TEXT NOT NULL, isolation_policy TEXT NOT NULL CHECK (isolation_policy IN ('project_workspace')), replace_runtime INTEGER NOT NULL CHECK (replace_runtime IN (0, 1)), result_allocation_id TEXT UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, result_assignment_id TEXT UNIQUE REFERENCES assignments(id) ON DELETE RESTRICT, objective_delivery_confirmed INTEGER NOT NULL DEFAULT 0 CHECK (objective_delivery_confirmed IN (0, 1)), CHECK ( ( requested_profile_id IS NULL AND requested_profile_version IS NULL ) OR ( requested_profile_id IS NOT NULL AND requested_profile_version IS NOT NULL AND requested_profile_version > 0 ) ) ) STRICT;
-- table worker_allocations on worker_allocations
CREATE TABLE "worker_allocations" ( id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, mode TEXT NOT NULL CHECK (mode IN ('adopt_existing', 'create_new', 'handoff')), started_by_command_id TEXT REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, started_at_unix_ms INTEGER NOT NULL, ended_at_unix_ms INTEGER ) STRICT;
-- table worker_cleanup_pins on worker_cleanup_pins
CREATE TABLE worker_cleanup_pins ( worker_id TEXT PRIMARY KEY NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, pinned_by TEXT NOT NULL, reason TEXT NOT NULL, pinned_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table worker_cleanup_policy on worker_cleanup_policy
CREATE TABLE worker_cleanup_policy ( singleton_id INTEGER PRIMARY KEY NOT NULL CHECK (singleton_id = 1), automatic_enabled INTEGER NOT NULL CHECK (automatic_enabled IN (0, 1)), schedule_minutes INTEGER NOT NULL CHECK (schedule_minutes BETWEEN 5 AND 10080), grace_period_ms INTEGER NOT NULL CHECK (grace_period_ms BETWEEN 60000 AND 7776000000), batch_size INTEGER NOT NULL CHECK (batch_size BETWEEN 1 AND 100), advisor_profile_id TEXT REFERENCES worker_profiles(id) ON DELETE RESTRICT, version INTEGER NOT NULL CHECK (version > 0), updated_by TEXT NOT NULL CHECK (length(updated_by) > 0), updated_at_unix_ms INTEGER NOT NULL CHECK (updated_at_unix_ms >= 0) ) STRICT;
-- table worker_cleanup_run_items on worker_cleanup_run_items
CREATE TABLE worker_cleanup_run_items ( run_id TEXT NOT NULL REFERENCES worker_cleanup_runs(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE RESTRICT, completion_receipt_id TEXT NOT NULL REFERENCES completion_receipts(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), expected_runtime_version INTEGER NOT NULL CHECK (expected_runtime_version > 0), adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_json TEXT, status TEXT NOT NULL CHECK (status IN ('pending', 'keep', 'review', 'reconciled', 'retired', 'failed', 'cancelled')), reason TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), next_attempt_at_unix_ms INTEGER NOT NULL, claim_token TEXT, claim_expires_at_unix_ms INTEGER, advisor_worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, advisor_assignment_id TEXT REFERENCES assignments(id) ON DELETE RESTRICT, advisor_completion_receipt_id TEXT REFERENCES completion_receipts(id) ON DELETE RESTRICT, advisor_recommendation TEXT CHECK (advisor_recommendation IN ('keep', 'retire', 'review')), advisor_artifact_id TEXT REFERENCES artifacts(id) ON DELETE RESTRICT, advisor_rationale TEXT, is_cleanup_advisor INTEGER NOT NULL DEFAULT 0 CHECK (is_cleanup_advisor IN (0, 1)), updated_at_unix_ms INTEGER NOT NULL, pane_instance_id TEXT, PRIMARY KEY (run_id, worker_id), UNIQUE (run_id, assignment_id), UNIQUE (advisor_worker_id), UNIQUE (advisor_assignment_id), UNIQUE (advisor_completion_receipt_id) ) STRICT;
-- table worker_cleanup_runs on worker_cleanup_runs
CREATE TABLE worker_cleanup_runs ( id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL UNIQUE, trigger TEXT NOT NULL CHECK (trigger IN ('preview', 'manual', 'scheduled')), preview INTEGER NOT NULL CHECK (preview IN (0, 1)), status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'completed', 'cancelled', 'failed')), advisor_state TEXT NOT NULL CHECK (advisor_state IN ('not_requested', 'unsupported', 'pending', 'completed', 'failed')), requested_by TEXT NOT NULL, policy_version INTEGER NOT NULL CHECK (policy_version > 0), grace_period_ms INTEGER NOT NULL, batch_size INTEGER NOT NULL, advisor_profile_id TEXT, cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancellation_requested IN (0, 1)), cancellation_command_id TEXT UNIQUE, cancelled_by TEXT, last_error TEXT, created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, completed_at_unix_ms INTEGER ) STRICT;
-- table worker_handoff_commands on worker_handoff_commands
CREATE TABLE worker_handoff_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, source_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, source_assignment_id TEXT NOT NULL, source_attempt_id TEXT NOT NULL, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), expected_source_project_version INTEGER NOT NULL CHECK (expected_source_project_version > 0), expected_source_assignment_version INTEGER NOT NULL CHECK (expected_source_assignment_version > 0), expected_source_attempt_version INTEGER NOT NULL CHECK (expected_source_attempt_version > 0), target_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, expected_target_project_version INTEGER NOT NULL CHECK (expected_target_project_version > 0), target_role TEXT NOT NULL CHECK (target_role IN ('member', 'orchestrator')), objective TEXT NOT NULL, role TEXT NOT NULL, isolation_policy TEXT NOT NULL CHECK (isolation_policy IN ('project_workspace')), source_runtime_adapter TEXT NOT NULL, source_runtime_session TEXT NOT NULL, source_runtime_workspace_id TEXT NOT NULL, source_terminal_id TEXT NOT NULL, source_tab_id TEXT, source_pane_id TEXT NOT NULL, source_provider_session_source TEXT, source_provider_session_provider TEXT, source_provider_session_kind TEXT, source_provider_session_value TEXT, target_runtime_adapter TEXT, target_runtime_session TEXT, target_runtime_workspace_id TEXT, target_terminal_id TEXT, target_tab_id TEXT, target_pane_id TEXT, target_provider_session_source TEXT, target_provider_session_provider TEXT, target_provider_session_kind TEXT, target_provider_session_value TEXT, target_runtime_claimed_at_unix_ms INTEGER, replaced_orchestrator_worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, result_allocation_id TEXT UNIQUE REFERENCES worker_allocations(id) ON DELETE RESTRICT, result_assignment_id TEXT UNIQUE REFERENCES assignments(id) ON DELETE RESTRICT, finished_at_unix_ms INTEGER, FOREIGN KEY (source_assignment_id, source_project_id) REFERENCES assignments(id, project_id) ON DELETE RESTRICT, FOREIGN KEY (source_attempt_id, source_assignment_id) REFERENCES assignment_attempts(id, assignment_id) ON DELETE RESTRICT, CHECK (source_project_id <> target_project_id), CHECK ( (target_role = 'member' AND replaced_orchestrator_worker_id IS NULL) OR ( target_role = 'orchestrator' AND replaced_orchestrator_worker_id IS NOT NULL ) ), CHECK ( ( source_provider_session_source IS NULL AND source_provider_session_provider IS NULL AND source_provider_session_kind IS NULL AND source_provider_session_value IS NULL ) OR ( source_provider_session_source IS NOT NULL AND source_provider_session_provider IS NOT NULL AND source_provider_session_kind IS NOT NULL AND source_provider_session_value IS NOT NULL ) ), CHECK ( ( target_runtime_adapter IS NULL AND target_runtime_session IS NULL AND target_runtime_workspace_id IS NULL AND target_terminal_id IS NULL AND target_tab_id IS NULL AND target_pane_id IS NULL AND target_provider_session_source IS NULL AND target_provider_session_provider IS NULL AND target_provider_session_kind IS NULL AND target_provider_session_value IS NULL AND target_runtime_claimed_at_unix_ms IS NULL ) OR ( target_runtime_adapter IS NOT NULL AND target_runtime_session IS NOT NULL AND target_runtime_workspace_id IS NOT NULL AND target_terminal_id IS NOT NULL AND target_pane_id IS NOT NULL AND target_runtime_claimed_at_unix_ms IS NOT NULL ) ), CHECK ( ( target_provider_session_source IS NULL AND target_provider_session_provider IS NULL AND target_provider_session_kind IS NULL AND target_provider_session_value IS NULL ) OR ( target_provider_session_source IS NOT NULL AND target_provider_session_provider IS NOT NULL AND target_provider_session_kind IS NOT NULL AND target_provider_session_value IS NOT NULL ) ), CHECK ( (result_allocation_id IS NULL AND result_assignment_id IS NULL) OR (result_allocation_id IS NOT NULL AND result_assignment_id IS NOT NULL) ) ) STRICT;
-- table worker_profile_mcp_servers on worker_profile_mcp_servers
CREATE TABLE worker_profile_mcp_servers ( profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (profile_id, profile_version, position), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table worker_profile_revisions on worker_profile_revisions
CREATE TABLE worker_profile_revisions ( profile_id TEXT NOT NULL REFERENCES worker_profiles(id) ON DELETE RESTRICT, version INTEGER NOT NULL CHECK (version > 0), name TEXT NOT NULL, runtime_adapter TEXT NOT NULL, provider TEXT NOT NULL, model TEXT, default_role TEXT NOT NULL, instructions_ref TEXT, sandbox_policy TEXT NOT NULL, worktree_policy TEXT NOT NULL, permission_policy TEXT NOT NULL, completion_contract TEXT NOT NULL, created_at_unix_ms INTEGER NOT NULL, PRIMARY KEY (profile_id, version) ) STRICT;
-- table worker_profile_skills on worker_profile_skills
CREATE TABLE worker_profile_skills ( profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (profile_id, profile_version, position), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table worker_profile_tools on worker_profile_tools
CREATE TABLE worker_profile_tools ( profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), value TEXT NOT NULL, PRIMARY KEY (profile_id, profile_version, position), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table worker_profiles on worker_profiles
CREATE TABLE worker_profiles ( id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL COLLATE NOCASE UNIQUE, current_version INTEGER NOT NULL CHECK (current_version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table worker_runtime_bindings on worker_runtime_bindings
CREATE TABLE "worker_runtime_bindings" ( worker_id TEXT PRIMARY KEY NOT NULL REFERENCES "workers"(id) ON DELETE CASCADE, adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_workspace_id TEXT NOT NULL, terminal_id TEXT NOT NULL, tab_id TEXT, pane_id TEXT NOT NULL, provider_session_source TEXT, provider_session_provider TEXT, provider_session_kind TEXT, provider_session_value TEXT, owns_tab INTEGER NOT NULL CHECK (owns_tab IN (0, 1)), observation_state TEXT NOT NULL CHECK (observation_state IN ('observed', 'missing', 'ambiguous')), version INTEGER NOT NULL CHECK (version > 0), last_observed_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, observed_status TEXT NOT NULL DEFAULT 'unknown' CHECK (observed_status IN ('idle', 'working', 'blocked', 'done', 'unknown')), process_state TEXT NOT NULL DEFAULT 'unknown' CHECK (process_state IN ('running', 'exited', 'unknown')), state_change_sequence INTEGER NOT NULL DEFAULT 0 CHECK (state_change_sequence >= 0), runtime_revision INTEGER NOT NULL DEFAULT 0 CHECK (runtime_revision >= 0), UNIQUE (adapter, runtime_session, terminal_id), CHECK ( ( provider_session_source IS NULL AND provider_session_provider IS NULL AND provider_session_kind IS NULL AND provider_session_value IS NULL ) OR ( provider_session_source IS NOT NULL AND provider_session_provider IS NOT NULL AND provider_session_kind IS NOT NULL AND provider_session_value IS NOT NULL ) ) ) STRICT;
-- table worker_session_end_commands on worker_session_end_commands
CREATE TABLE worker_session_end_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), expected_runtime_version INTEGER CHECK (expected_runtime_version IS NULL OR expected_runtime_version > 0), finished_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table workers on workers
CREATE TABLE "workers" ( id TEXT PRIMARY KEY NOT NULL, profile_id TEXT, profile_version INTEGER, desired_state TEXT NOT NULL CHECK (desired_state IN ('running')), version INTEGER NOT NULL CHECK (version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, ended_at_unix_ms INTEGER, ownership_kind TEXT NOT NULL DEFAULT 'external' CHECK (ownership_kind IN ('external', 'yard_owned', 'system_ephemeral')), parent_worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT, CHECK ( (profile_id IS NULL AND profile_version IS NULL) OR (profile_id IS NOT NULL AND profile_version IS NOT NULL) ) ) STRICT;
-- table workspace_project_creation_commands on workspace_project_creation_commands
CREATE TABLE workspace_project_creation_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, project_name TEXT NOT NULL, runtime_adapter TEXT NOT NULL, runtime_session TEXT NOT NULL, workspace_label TEXT NOT NULL, cwd TEXT NOT NULL, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL CHECK (profile_version > 0), orchestrator_objective TEXT NOT NULL, canvas_x REAL NOT NULL, canvas_y REAL NOT NULL, canvas_width REAL NOT NULL, canvas_height REAL NOT NULL, result_runtime_workspace_id TEXT, result_project_id TEXT UNIQUE REFERENCES projects(id) ON DELETE RESTRICT, result_worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, finished_at_unix_ms INTEGER, workflow_profile_id TEXT NOT NULL DEFAULT 'yard:standard-orchestrator', workflow_profile_version INTEGER NOT NULL DEFAULT 1 CHECK (workflow_profile_version > 0), FOREIGN KEY (profile_id, profile_version) REFERENCES worker_profile_revisions(profile_id, version) ON DELETE RESTRICT, CHECK ( ( result_runtime_workspace_id IS NULL AND result_project_id IS NULL AND result_worker_id IS NULL ) OR ( result_runtime_workspace_id IS NOT NULL AND result_project_id IS NOT NULL AND result_worker_id IS NOT NULL ) ) ) STRICT;
-- table yard_installation on yard_installation
CREATE TABLE yard_installation ( singleton_id INTEGER PRIMARY KEY NOT NULL CHECK (singleton_id = 1), installation_uuid TEXT NOT NULL UNIQUE, created_at_unix_ms INTEGER NOT NULL ) STRICT;
-- table yard_orchestrator on yard_orchestrator
CREATE TABLE "yard_orchestrator" ( singleton_id INTEGER PRIMARY KEY NOT NULL CHECK (singleton_id = 1), worker_id TEXT UNIQUE REFERENCES workers(id) ON DELETE RESTRICT, version INTEGER NOT NULL CHECK (version > 0), created_at_unix_ms INTEGER NOT NULL, updated_at_unix_ms INTEGER NOT NULL, workflow_profile_id TEXT NOT NULL DEFAULT 'yard:standard-orchestrator' CHECK (workflow_profile_id = 'yard:standard-orchestrator'), workflow_profile_version INTEGER NOT NULL CHECK (workflow_profile_version > 0), FOREIGN KEY (workflow_profile_id, workflow_profile_version) REFERENCES "orchestrator_workflow_profile_revisions"(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table yard_orchestrator_configure_commands on yard_orchestrator_configure_commands
CREATE TABLE "yard_orchestrator_configure_commands" ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_worker_version INTEGER NOT NULL CHECK (expected_worker_version > 0), expected_orchestrator_version INTEGER NOT NULL CHECK (expected_orchestrator_version > 0), replaced_worker_id TEXT REFERENCES workers(id) ON DELETE RESTRICT, result_orchestrator_version INTEGER NOT NULL CHECK (result_orchestrator_version > 0), finished_at_unix_ms INTEGER NOT NULL, workflow_profile_id TEXT NOT NULL DEFAULT 'yard:standard-orchestrator' CHECK (workflow_profile_id = 'yard:standard-orchestrator'), workflow_profile_version INTEGER NOT NULL CHECK (workflow_profile_version > 0), FOREIGN KEY (workflow_profile_id, workflow_profile_version) REFERENCES "orchestrator_workflow_profile_revisions"(profile_id, version) ON DELETE RESTRICT ) STRICT;
-- table yard_orchestrator_prompt_commands on yard_orchestrator_prompt_commands
CREATE TABLE yard_orchestrator_prompt_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_orchestrator_version INTEGER NOT NULL CHECK (expected_orchestrator_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- table yard_orchestrator_route_commands on yard_orchestrator_route_commands
CREATE TABLE yard_orchestrator_route_commands ( command_id TEXT PRIMARY KEY NOT NULL REFERENCES command_acknowledgements(id) ON DELETE RESTRICT, orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_orchestrator_version INTEGER NOT NULL CHECK (expected_orchestrator_version > 0), target_project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, target_orchestrator_worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, expected_project_version INTEGER NOT NULL CHECK (expected_project_version > 0), prompt_text TEXT NOT NULL, runtime_session TEXT NOT NULL, runtime_pane_id TEXT NOT NULL, result_runtime_status TEXT, submitted_at_unix_ms INTEGER, CHECK ( (result_runtime_status IS NULL AND submitted_at_unix_ms IS NULL) OR ( result_runtime_status IS NOT NULL AND submitted_at_unix_ms IS NOT NULL ) ) ) STRICT;
-- trigger automation_create_command_project_scope on automation_create_command_projects
CREATE TRIGGER automation_create_command_project_scope BEFORE INSERT ON automation_create_command_projects WHEN ( SELECT scope_kind FROM automation_create_commands WHERE command_id = NEW.command_id ) = 'project_orchestrator' AND NEW.project_id <> ( SELECT scope_project_id FROM automation_create_commands WHERE command_id = NEW.command_id ) BEGIN SELECT RAISE(ABORT, 'project automation selection must match its scope'); END;
-- trigger automation_create_command_workstream_project on automation_create_command_projects
CREATE TRIGGER automation_create_command_workstream_project BEFORE INSERT ON automation_create_command_projects WHEN ( SELECT scope_kind FROM automation_create_commands WHERE command_id = NEW.command_id ) = 'workstream_coordination_node' AND NOT EXISTS ( SELECT 1 FROM automation_create_commands acc JOIN coordination_node_projects cnp ON cnp.node_id = acc.scope_node_id WHERE acc.command_id = NEW.command_id AND cnp.project_id = NEW.project_id ) BEGIN SELECT RAISE(ABORT, 'workstream automation project is not attached'); END;
-- trigger automation_create_commands_workstream_scope on automation_create_commands
CREATE TRIGGER automation_create_commands_workstream_scope BEFORE INSERT ON automation_create_commands WHEN NEW.scope_kind = 'workstream_coordination_node' AND NOT EXISTS ( SELECT 1 FROM coordination_nodes WHERE id = NEW.scope_node_id AND kind = 'workstream' ) BEGIN SELECT RAISE(ABORT, 'automation scope requires a workstream coordination node'); END;
-- trigger automation_runs_workstream_scope on automation_runs
CREATE TRIGGER automation_runs_workstream_scope BEFORE INSERT ON automation_runs WHEN NEW.scope_kind = 'workstream_coordination_node' AND NOT EXISTS ( SELECT 1 FROM coordination_nodes WHERE id = NEW.scope_node_id AND kind = 'workstream' ) BEGIN SELECT RAISE(ABORT, 'automation scope requires a workstream coordination node'); END;
-- trigger automation_selected_project_scope on automation_selected_projects
CREATE TRIGGER automation_selected_project_scope BEFORE INSERT ON automation_selected_projects WHEN ( SELECT scope_kind FROM automations WHERE id = NEW.automation_id ) = 'project_orchestrator' AND NEW.project_id <> ( SELECT scope_project_id FROM automations WHERE id = NEW.automation_id ) BEGIN SELECT RAISE(ABORT, 'project automation selection must match its scope'); END;
